// What the landing page knows about one example deck, as props for the player
// and the gallery. Built at build time by src/data/examples.ts from the registry
// (src/data/examples.json), the deck's own files and the fixtures `make demo`
// and the generators in scripts/ write.

/** One step as the deck reported it while `make demo` walked it. */
export type ExampleState = {
  slide: number;
  beat: number;
  beats: number;
  lead: string;
  body: string;
};

/** Generated by `make demo` at 640 and 1280 wide, AVIF and WebP: `${base}-1280.avif`. */
export type Poster = { base: string; width: number; height: number };

/** A step the loop video shows from `t` seconds on. */
export type LoopMark = { t: number; slide: number; beat: number };

/** The hero loop: `${base}.webm` and `${base}.mp4`, with the step shown at each time. */
export type Loop = { base: string; width: number; height: number; marks: LoopMark[] };

export type ProvenanceKind = "agent" | "talk" | "template" | "hand";

/** How the deck was made, as the gallery and the player label it. */
export type Provenance = { kind: ProvenanceKind; label: string };

/** The recorded agent run behind a deck, rounded for reading. */
export type RunSummary = {
  prompt: string;
  /** repo: this repository's agent setup; init: a fresh project with decks init. */
  setup: "repo" | "init";
  turns: number;
  minutes: string;
  cost: string;
};

/** Who edited the agent's draft: a person, or a second Claude Code session. */
export type Editor = "hand" | "claude";

/** The edit after the agent's draft, from scripts/edits.mjs, and who made it. */
export type Edits = {
  by: Editor;
  files: number;
  insertions: number;
  deletions: number;
  pairs: { file: string; before: string; after: string }[];
};

export type Example = {
  /** Directory name under examples/, and the path segment under /demo/. */
  name: string;
  title: string;
  /** The static build: /demo/<name>/. */
  href: string;
  slides: number;
  slideTitles: string[];
  /** The first story slide, where the poster is taken and the player starts. */
  startSlide: number;
  /** The step on the start slide the poster shows and the player starts from (0-based). */
  startBeat: number;
  states: ExampleState[];
  provenance: Provenance;
  /** Generated by `make demo`; null until it has run. */
  poster: Poster | null;
  loop: Loop | null;
  run: RunSummary | null;
  edits: Edits | null;
};

export const POSTER_WIDTHS = [640, 1280] as const;

/** srcset for one format: "/posters/tides-640.avif 640w, /posters/tides-1280.avif 1280w". */
export const posterSrcset = (poster: Poster, ext: "avif" | "webp") =>
  POSTER_WIDTHS.map((width) => `${poster.base}-${width}.${ext} ${width}w`).join(", ");

/** The recorded state for a position, if `make demo` captured one. */
export const stateAt = (example: Pick<Example, "states">, slide: number, beat: number) =>
  example.states.find((state) => state.slide === slide && state.beat === beat);

/** The first slide with a caption: where Play starts over from the end of the deck. */
export const firstStorySlide = (example: Pick<Example, "states" | "startSlide">) =>
  example.states.find((state) => state.lead)?.slide ?? example.startSlide;

/** The step the loop shows at `time` seconds: the last mark at or before it. */
export function markAt(loop: Pick<Loop, "marks">, time: number): LoopMark | null {
  let current: LoopMark | null = null;
  for (const mark of loop.marks) {
    if (mark.t <= time) current = mark;
    else break;
  }
  return current ?? loop.marks[0] ?? null;
}

/** "edited by hand" or "fact-checked and edited in a second Claude Code session". */
export const editedBy = (by: Editor) =>
  by === "claude" ? "fact-checked and edited in a second Claude Code session" : "edited by hand";

/** "+30/−18 in 10 files": the edit's size, as git counts it. */
export const editSize = (edits: Pick<Edits, "insertions" | "deletions" | "files">) =>
  `+${edits.insertions}/−${edits.deletions} in ${edits.files} files`;

/** One sentence under the player: how long the draft took and how much the edit changed. */
export function draftLine(run: RunSummary, edits: Edits | null): string {
  const where =
    run.setup === "init"
      ? "in a fresh project set up with decks init"
      : "with this repository's agent setup";
  const minutes = Math.round(Number(run.minutes));
  const edit = edits ? `, then ${editedBy(edits.by)} (${editSize(edits)})` : "";
  return `Drafted in ${minutes} minutes from this prompt ${where}${edit}.`;
}
